const Ic=({d,size=18,color="currentColor",sw=1.8})=>(<svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth={sw} strokeLinecap="round" strokeLinejoin="round"><path d={d}/></svg>);
const Btn=({children,onClick,variant="primary",size="md",icon,full,disabled,loading,C})=>{
  const sz={sm:{padding:"6px 14px",fontSize:13},md:{padding:"10px 20px",fontSize:14},lg:{padding:"14px 28px",fontSize:15}};
  const vr={primary:{background:C.accent,color:"#fff",boxShadow:`0 4px 20px ${C.accentGlow}`},ghost:{background:"transparent",color:C.muted,border:`1px solid ${C.border}`},danger:{background:"rgba(239,68,68,0.12)",color:C.red,border:"1px solid rgba(239,68,68,0.3)"},success:{background:"rgba(34,197,94,0.12)",color:C.green,border:"1px solid rgba(34,197,94,0.3)"}};
  return(<button onClick={onClick} disabled={disabled||loading} style={{display:"inline-flex",alignItems:"center",gap:6,fontFamily:"inherit",fontWeight:600,cursor:(disabled||loading)?"not-allowed":"pointer",border:"none",borderRadius:10,transition:"all .18s",opacity:(disabled||loading)?0.6:1,width:full?"100%":undefined,justifyContent:full?"center":undefined,...sz[size],...vr[variant]}}>{icon&&!loading&&<Ic d={IC[icon]} size={15}/>}{loading?"Aguarde...":children}</button>);
};
const Inp=({label,value,onChange,type="text",placeholder,suffix,prefix,help,readOnly,C})=>(
  <div style={{display:"flex",flexDirection:"column",gap:6}}>
    {label&&<label style={{fontSize:12,fontWeight:600,color:C.muted,textTransform:"uppercase",letterSpacing:".06em"}}>{label}</label>}
    <div style={{position:"relative",display:"flex",alignItems:"center"}}>
      {prefix&&<span style={{position:"absolute",left:12,fontSize:13,color:C.muted,pointerEvents:"none"}}>{prefix}</span>}
      <input type={type} value={value} onChange={e=>onChange&&onChange(e.target.value)} placeholder={placeholder} readOnly={readOnly}
        style={{width:"100%",background:readOnly?C.surface:C.inputBg,border:`1px solid ${C.border}`,borderRadius:8,padding:prefix?"10px 12px 10px 28px":suffix?"10px 36px 10px 12px":"10px 12px",color:C.text,fontSize:14,fontFamily:"inherit",outline:"none",boxSizing:"border-box"}}
        onFocus={e=>{if(!readOnly)e.target.style.borderColor=C.accent}} onBlur={e=>e.target.style.borderColor=C.border}/>
      {suffix&&<span style={{position:"absolute",right:12,fontSize:13,color:C.muted,pointerEvents:"none"}}>{suffix}</span>}
    </div>
    {help&&<span style={{fontSize:11,color:C.dim}}>{help}</span>}
  </div>
);
const Sel=({label,value,onChange,options,C})=>(
  <div style={{display:"flex",flexDirection:"column",gap:6}}>
    {label&&<label style={{fontSize:12,fontWeight:600,color:C.muted,textTransform:"uppercase",letterSpacing:".06em"}}>{label}</label>}
    <select value={value} onChange={e=>onChange(e.target.value)} style={{background:C.inputBg,border:`1px solid ${C.border}`,borderRadius:8,padding:"10px 12px",color:C.text,fontSize:14,fontFamily:"inherit",outline:"none"}}>
      {options.map(o=><option key={o.value} value={o.value}>{o.label}</option>)}
    </select>
  </div>
);
const Card=({children,style,C,onClick})=>(<div onClick={onClick} style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:14,padding:20,...style,cursor:onClick?"pointer":undefined}}>{children}</div>);
const Badge=({children,color,C})=>{const col=color||C.accent;return <span style={{background:col+"22",color:col,fontSize:11,fontWeight:700,padding:"3px 8px",borderRadius:6,display:"inline-block"}}>{children}</span>;};
const Modal=({title,onClose,children,wide,wider,C})=>(
  <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,.65)",zIndex:1000,display:"flex",alignItems:"center",justifyContent:"center",padding:20}} onClick={e=>e.target===e.currentTarget&&onClose()}>
    <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:18,width:"100%",maxWidth:wider?960:wide?700:500,maxHeight:"92vh",overflowY:"auto",padding:28}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:22}}>
        <h2 style={{margin:0,fontSize:18,fontWeight:700,color:C.text}}>{title}</h2>
        <button onClick={onClose} style={{background:"none",border:"none",color:C.muted,cursor:"pointer"}}><Ic d={IC.x} size={20}/></button>
      </div>
      {children}
    </div>
  </div>
);
const StatCard=({label,value,sub,color,icon,C,onClick})=>{const col=color||C.accent;return(<div onClick={onClick} style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:14,padding:20,cursor:onClick?"pointer":"default",transition:"transform .15s,box-shadow .15s"}} onMouseEnter={e=>{if(onClick){e.currentTarget.style.transform="translateY(-2px)";e.currentTarget.style.boxShadow=`0 8px 24px ${col}20`;}}} onMouseLeave={e=>{e.currentTarget.style.transform="";e.currentTarget.style.boxShadow="";}}>
  <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start"}}>
    <div><div style={{fontSize:12,color:C.muted,fontWeight:600,textTransform:"uppercase",letterSpacing:".06em",marginBottom:8}}>{label}</div><div style={{fontSize:26,fontWeight:800,color:col}}>{value}</div>{sub&&<div style={{fontSize:12,color:C.dim,marginTop:4}}>{sub}</div>}</div>
    <div style={{background:col+"18",borderRadius:10,padding:10}}><Ic d={IC[icon]} size={20} color={col}/></div>
  </div>
  {onClick&&<div style={{fontSize:11,color:col,marginTop:10,display:"flex",alignItems:"center",gap:4}}>Ver detalhes <Ic d={IC.arr} size={11} color={col}/></div>}
</div>);};
const uploadFotos=async(files,pasta)=>{
  const urls=[];
  for(const file of files){
    const ext=file.name.split(".").pop();
    const path=pasta+"/"+Date.now()+"_"+Math.random().toString(36).slice(2)+"."+ext;
    const {error}=await supabase.storage.from("fotos").upload(path,file,{upsert:true});
    if(!error){const {data}=supabase.storage.from("fotos").getPublicUrl(path);urls.push(data.publicUrl);}
  }
  return urls;
};
